# ----------------------------------------------------------------------------------------
# Text outlines (Procedure A, brief section 5.4)
# ----------------------------------------------------------------------------------------

_PATH_CMD_RE = re.compile(r"([MLHVCZ])([^MLHVCZ]*)")
_NUM_RE = re.compile(r"-?\d+(?:\.\d+)?")


def _path_tokens(d):
    """[(command, [numbers...]), ...] for the absolute-only outlines in the tables."""
    return [(cmd, [float(n) for n in _NUM_RE.findall(rest)]) for cmd, rest in _PATH_CMD_RE.findall(d)]


def glyph_ink_x(d):
    """Min/max x of an outline in font units (x coordinates of M/L/C points and H values;
    Pilat keeps its horizontal extrema on-curve, so control points do not widen the box)."""
    xs = []
    for cmd, nums in _path_tokens(d):
        if cmd in "MLC":
            xs.extend(nums[0::2])
        elif cmd == "H":
            xs.extend(nums)
    return min(xs), max(xs)


def text_ink_width(text, glyphs, kern, size, tracking=0.0, word_extra=0.0):
    """Ink width in px of a string laid out exactly as text_paths lays it out (self-test)."""
    _, ink_min, ink_max = _layout(text, glyphs, kern, size, tracking, word_extra)
    return ink_max - ink_min


def _layout(text, glyphs, kern, size, tracking, word_extra):
    s = size / 1000.0
    pen_x = 0.0
    placed = []
    ink_min = None
    ink_max = None
    for i, ch in enumerate(text):
        if ch not in glyphs:
            raise PanelError("no outline for %r in %r" % (ch, text))
        adv, d = glyphs[ch]
        if d:  # space has no outline
            placed.append((pen_x, d))
            x0, x1 = glyph_ink_x(d)
            ink_min = pen_x + x0 * s if ink_min is None else min(ink_min, pen_x + x0 * s)
            ink_max = pen_x + x1 * s if ink_max is None else max(ink_max, pen_x + x1 * s)
        if i + 1 < len(text):
            adv += kern.get(ch + text[i + 1], 0)
        pen_x += adv * s + tracking + (word_extra if ch == " " else 0.0)
    if ink_min is None:
        raise PanelError("label %r has no ink" % text)
    return placed, ink_min, ink_max


def text_paths(text, cx, baseline_y, glyphs, kern, size, tracking=0.0, word_extra=0.0,
               fill=COL_INK, opacity=INK_OPACITY, elem_id=None, indent="    "):
    """Return a <g> of one <path> per glyph, ink-centred on cx with the baseline at baseline_y.
    One path per glyph with its own matrix is the simplest correct form: NanoSVG bakes the
    matrix and generate_dark_panel.py recolours each style="fill:...". The group id must never
    end in a placeholder suffix (PanelHelper::findMatched would pick it up)."""
    s = size / 1000.0
    placed, ink_min, ink_max = _layout(text, glyphs, kern, size, tracking, word_extra)
    shift = cx - (ink_min + ink_max) / 2.0
    gid = elem_id or ("label_" + re.sub(r"[^A-Za-z0-9]", "_", text).lower())
    if PLACEHOLDER_RE.match(gid):
        raise PanelError("label id %r ends in a placeholder suffix" % gid)
    out = ['%s<g id="%s" aria-label="%s">' % (indent, gid, text)]
    for x, d in placed:
        out.append('%s  <path transform="matrix(%.6f,0,0,%.6f,%.4f,%.4f)" style="fill:%s;fill-opacity:%s" d="%s"/>'
                   % (indent, s, s, x + shift, baseline_y, fill, opacity, d))
    out.append("%s</g>" % indent)
    return "\n".join(out)


class PanelError(Exception):
    pass


def self_test():
    """The embedded tables must reproduce the shipped label widths (brief 5.3 / Appendix C, D)."""
    refs = [("CLOCK", 27.622), ("CV", 10.786), ("RESET", 25.741), ("RECORD", 33.552)]
    for text, ref in refs:
        got = text_ink_width(text, LABEL_GLYPHS, LABEL_KERN, SIZE_LABEL, TRACK_LABEL, 0.0)
        if abs(got - ref) > 0.002:
            raise PanelError("self-test: %s ink width %.3f, expected %.3f" % (text, got, ref))
    got = text_ink_width("CUE RESEARCH", NAME_GLYPHS, NAME_KERN, SIZE_NAME, 0.0, WORD_NAME)
    if abs(got - 32.569) > 0.002:
        raise PanelError("self-test: CUE RESEARCH ink width %.3f, expected 32.569" % got)


# ----------------------------------------------------------------------------------------
# Geometry tables (DESIGN.md 3.4 and 4.8). Every number here is a Rack pixel.
# ----------------------------------------------------------------------------------------

def circle(eid, cx, cy, r, fill):
    return {"tag": "circle", "id": eid, "cx": cx, "cy": cy, "r": r, "fill": fill}


def rect(eid, x, y, w, h, rx, fill, layer):
    return {"tag": "rect", "id": eid, "x": x, "y": y, "w": w, "h": h, "rx": rx, "fill": fill, "layer": layer}


def rule(eid, x, y1, y2, width=1.2):
    """A vertical silkscreen rule (a <line> in ink colour) in the background layer."""
    return {"id": eid, "x": x, "y1": y1, "y2": y2, "width": width}


def label(eid, text, cx, baseline):
    return {"id": eid, "text": text, "cx": cx, "baseline": baseline}


def label_id_for(anchor_id):
    """label id for an anchor: strip the placeholder suffix so the label never matches one."""
    return "label_" + re.sub(r"_(%s)$" % "|".join(PLACEHOLDER_SUFFIXES), "", anchor_id)


def slug(text):
    return re.sub(r"[^A-Za-z0-9]+", "_", text).strip("_").lower()


def kit_panel():
    """VX Drums (the kit): 7 columns x 4 knob rows, strike lights, jack row. DESIGN.md 3.4."""
    cols = [93, 152, 211, 270, 329, 388, 447]     # +45 px: the CV jack column sits at x 40
    titles = ["BASS DRUM", "SNARE", "CLAP", "PERC", "CLOSED HAT", "OPEN HAT", "MASTER"]
    voices = ["bd", "sd", "cp", "perc", "ch", "oh"]
    # DESIGN-KITS.md 6: every voice column carries the same four labels. The third knob is
    # SHAPE whatever the column's model makes of it (punch, snap, spread, drive, metal...);
    # the tooltip names the model's own parameter.
    knob_params = ["tune", "decay", "shape", "level"]
    # Shifted down 18 px on 2026-09-02 (Bret: the top was cramped, the bottom had room);
    # the bottom screws are gone from this panel, so the jack row may sit this low.
    knob_rows = [102, 156, 210, 264]
    title_baseline = 76
    light_cy = 62
    master_cx = cols[6]
    master = [("m_accent_knob", "ACCENT", knob_rows[0]),
              ("m_vary_knob", "VARY", knob_rows[1]),        # per-hit random spread (Bret, 2026-09-02)
              ("m_drive_knob", "DRIVE", knob_rows[2]),
              ("m_volume_knob", "VOLUME", knob_rows[3])]
    jack_cy = 346
    jack_label_baseline = jack_cy - JACK_LABEL_DY            # 324.7
    inputs = [("trig_input", "TRIG", 44), ("acc_input", "ACC", 84)]
    # Individual outs first, the stereo mix at the right end (Bret, 2026-09-02).
    outputs = [("bd_output", "BD", 177), ("sd_output", "SD", 217), ("cp_output", "CP", 257),
               ("perc_output", "PERC", 297), ("ch_output", "CH", 337), ("oh_output", "OH", 377),
               ("left_output", "L", 417), ("right_output", "R", 457)]
    # Poly CV inputs, one per knob row, in a column left of the knobs (Bret, 2026-09-02):
    # channel c drives column c's knob on that row, channel 7 the master knob, mono normals
    # to all. Labelled below the jack on the knob-label baseline of the row.
    cv_inputs = [("tune_cv_input", "TUNE CV", knob_rows[0]), ("decay_cv_input", "DECAY CV", knob_rows[1]),
                 ("shape_cv_input", "SHAPE CV", knob_rows[2]), ("level_cv_input", "LEVEL CV", knob_rows[3])]
    cv_cx = 40

    # The KIT readout (DESIGN-KITS.md 6): a dark plate top right, read with findNamedRect and
    # painted over by VXDrumsKitDisplay; a KIT label to its left. Dark in BOTH themes, so it
    # is re-inserted after the dark pass (see reinsert_display_rects). It stays
    # clear of the top-right screw square (x 465-480, y 0-15): the rect starts at y 18.
    kit_display = (363, 18, 116, 20)
    kit_label_cx, kit_label_baseline = 348, 30

    # Vertical rules between the six drum columns (Bret, 2026-09-02), at the column
    # midpoints, from just above knob row 1 to just below the LEVEL labels.
    rules = [rule("column_rule_%d" % (i + 1), (cols[i] + cols[i + 1]) / 2.0,
                  knob_rows[0] - 12, knob_rows[3] + KNOB_LABEL_DY + 6)
             for i in range(5)]
    rects = [rect("outputs_plate", 157, 312, 320, 58, 4.5, COL_PLATE, "background"),
             rect("kit_display", kit_display[0], kit_display[1], kit_display[2], kit_display[3], 3,
                  COL_DARK_PLATE, "anchors")]
    anchors = []
    labels = [label("label_kit", "KIT", kit_label_cx, kit_label_baseline)]
    for i, title in enumerate(titles):
        labels.append(label("label_title_" + slug(title), title, cols[i], title_baseline))
    for i, v in enumerate(voices):
        cx = cols[i]
        anchors.append(circle(v + "_light", cx, light_cy, DOT_R, COL_DOT))
        for k, p in enumerate(knob_params):
            cy = knob_rows[k]
            aid = "%s_%s_knob" % (v, p)
            anchors.append(circle(aid, cx, cy, DOT_R, COL_DOT))
            labels.append(label(label_id_for(aid), p.upper(), cx, cy + KNOB_LABEL_DY))
    for aid, text, cy in master:
        anchors.append(circle(aid, master_cx, cy, DOT_R, COL_DOT))
        labels.append(label(label_id_for(aid), text, master_cx, cy + KNOB_LABEL_DY))
    for aid, text, cx in inputs + outputs:
        anchors.append(circle(aid, cx, jack_cy, PORT_R, COL_MARK))
        labels.append(label(label_id_for(aid), text, cx, jack_label_baseline))
    for aid, text, cy in cv_inputs:
        anchors.append(circle(aid, cv_cx, cy, PORT_R, COL_MARK))
        labels.append(label(label_id_for(aid), text, cv_cx, cy + KNOB_LABEL_DY))

    return {
        "name": "VX DRUMS",
        "stem": "vx_drums_panel",
        "res_dir": "vx_drums",
        "docs_dir": "vx-drums",
        "widget": "src/modules/VXDrums/VXDrumsWidget.hpp",
        "rects": rects,
        "rules": rules,
        "anchors": anchors,
        "labels": labels,
        "notes": [
            "Vertical rules (1.2 px ink) between the six drum columns at x 122.5 181.5 240.5 299.5 358.5, y 90-293.",
            "CV column at x 40: tune_cv_input / decay_cv_input / shape_cv_input / level_cv_input on the knob rows (poly).",
            "Kit strip: 7 columns at cx 93 152 211 270 329 388 447 (BD SD CP PERC CH OH MASTER); titles baseline 76.",
            "Strike lights (MediumLight) at (cx, 62) for the six voices. Knob rows cy 102 156 210 264 (RoundBlackKnob),",
            "labels at cy + 23, TUNE DECAY SHAPE LEVEL on every voice column; the master column has ACCENT (row 1),",
            "VARY (row 2), DRIVE (row 3), VOLUME (row 4).",
            "kit_display (363,18) 116 x 20 dark plate, rx 3, top right (findNamedRect; VXDrumsKitDisplay paints it);",
            "KIT label ink-centred at cx 348, baseline 30. The top-right screw square is x 465-480, y 0-15.",
            "Jack row cy 346, labels at 324.7: TRIG 44 and ACC 84 (inputs, no plate); outputs on the #d2d2d3 plate",
            "at pitch 40: BD 177, SD 217, CP 257, PERC 297, CH 337, OH 377, L 417, R 457.",
        ],
    }


def sequencer_panel():
    """VX Drum Sequencer: grid area, 16 memory buttons, one control/jack row with the outputs.
    DESIGN.md 4.8 as revised 2026-09-02: external clock only (the INT switch, BPM knob,
    BPM readout, RUN switch and SWING knob are gone), so the freed height goes to the grid."""
    mem_cy = 262
    mem_label_baseline = 282
    ctrl_cy = 340
    ctrl_label_baseline = ctrl_cy - JACK_LABEL_DY            # 318.7
    controls = [("clk_input", "CLK", 40, "jack"), ("rst_input", "RST", 80, "jack"),
                ("mem_input", "MEM", 120, "jack"), ("rewind_button", "RWD", 176, "dot"),
                ("random_button", "RND", 216, "dot"), ("trig_output", "TRIG", 425, "jack"),
                ("acc_output", "ACC", 465, "jack")]

    rects = [rect("grid_area", 15, 42, 465, 200, 4.5, COL_PLATE, "background"),
             rect("outputs_plate", 403, 304, 82, 70, 4.5, COL_PLATE, "background")]   # extended down to y 374 (Bret, 2026-09-02); it may crowd the bottom-right screw
    anchors = []
    labels = []
    for n in range(1, 17):
        cx = 38 + 28 * (n - 1)      # 16 buttons across the 33 HP panel, 38..458
        aid = "mem_%d_button" % n
        anchors.append(circle(aid, cx, mem_cy, DOT_R, COL_DOT))
        labels.append(label(label_id_for(aid), str(n), cx, mem_label_baseline))
    for aid, text, cx, kind in controls:
        anchors.append(circle(aid, cx, ctrl_cy, PORT_R if kind == "jack" else DOT_R,
                              COL_MARK if kind == "jack" else COL_DOT))
        labels.append(label(label_id_for(aid), text, cx, ctrl_label_baseline))

    return {
        "name": "VX DRUM SEQ",
        "stem": "vx_drum_sequencer_panel",
        "res_dir": "vx_drum_sequencer",
        "docs_dir": "vx-drum-sequencer",
        "widget": "src/modules/VXDrumSequencer/VXDrumSequencerWidget.hpp",
        "rects": rects,
        "anchors": anchors,
        "labels": labels,
        "notes": [
            "External clock only (owner decision 2026-09-02): no INT switch, BPM knob, BPM readout, RUN switch or SWING knob.",
            "grid_area (15,42) 465 x 200 is painted over by the grid widget; the plate is the browser fallback.",
            "Memory buttons mem_1..mem_16 at cx 38 + 28(n-1), cy 262 (VCVLightBezel), numbers at baseline 282.",
            "One control row cy 340, labels at 318.7: CLK 40, RST 80, MEM 120 (jacks); RWD 176, RND 216 (VCVButton);",
            "outputs plate (403,304) 82 x 70 with TRIG 425 (poly) and ACC 465. Only the bottom screw squares",
            "(x 15-30 and 465-480, y 365-380) are on this panel; the top strip holds the wordmark / name box alone.",
        ],
    }


# ----------------------------------------------------------------------------------------
# SVG emission
# ----------------------------------------------------------------------------------------

def fmt(v):
    """Compact decimal: 306.7, 11.764, 379.4286, 40 (never scientific notation)."""
    if isinstance(v, int):
        return str(v)
    s = ("%.4f" % v).rstrip("0").rstrip(".")
    return "0" if s in ("", "-0") else s


def frame_geometry():
    """Frame placement in Rack px from the raw bbox (Appendix B) and the FRAME_X/Y target."""
    x0, y0, x1, y1 = FRAME_RAW_BBOX
    w = (x1 - x0) * RAW2PX
    h = (y1 - y0) * RAW2PX
    return FRAME_X, FRAME_Y, w, h


def emit_branding(name):
    fx, fy, fw, fh = frame_geometry()
    name_cx = fx + fw / 2.0
    name_baseline = fy + fh / 2.0 + NAME_CAP_PX / 2.0      # name ink centred in the frame
    wm_tx = WORDMARK_X - RAW2PX * WORDMARK_RAW_MIN[0]
    wm_ty = WORDMARK_Y - RAW2PX * WORDMARK_RAW_MIN[1]
    fr_tx = FRAME_X - RAW2PX * FRAME_RAW_BBOX[0]
    fr_ty = FRAME_Y - RAW2PX * FRAME_RAW_BBOX[1]
    lines = []
    lines.append('    <!-- VOXGLITCH wordmark (arpseq path50), ink top-left at (%s, %s) -->' % (fmt(WORDMARK_X), fmt(WORDMARK_Y)))
    lines.append('    <g id="voxglitch_wordmark" transform="matrix(%.7f,0,0,%.7f,%.4f,%.4f)">' % (RAW2PX, RAW2PX, wm_tx, wm_ty))
    lines.append('      <path id="voxglitch_wordmark_path" style="opacity:0.78;fill:%s;fill-opacity:1;stroke:none" d="%s"/>' % (COL_ART, WORDMARK_D))
    lines.append('    </g>')
    lines.append('    <!-- module-name frame (cue_research path6-5) at (%s, %s), %s x %s -->' % (fmt(FRAME_X), fmt(FRAME_Y), fmt(fw), fmt(fh)))
    lines.append('    <g id="module_name_box" transform="matrix(%.7f,0,0,%.7f,%.4f,%.4f)">' % (RAW2PX, RAW2PX, fr_tx, fr_ty))
    lines.append('      <path id="module_name_box_path" style="fill:%s;fill-opacity:%s;stroke:none" d="%s"/>' % (COL_INK, INK_OPACITY, FRAME_D))
    lines.append('    </g>')
    lines.append('    <!-- module name, Pilat Condensed Bold %s px, ink-centred in the frame -->' % fmt(SIZE_NAME))
    lines.append(text_paths(name, name_cx, name_baseline, NAME_GLYPHS, NAME_KERN, SIZE_NAME,
                            tracking=0.0, word_extra=WORD_NAME, elem_id="module_name_text"))
    return lines


def emit_rect(r, indent="    "):
    return '%s<rect id="%s" x="%s" y="%s" width="%s" height="%s" rx="%s" fill="%s"/>' % (
        indent, r["id"], fmt(r["x"]), fmt(r["y"]), fmt(r["w"]), fmt(r["h"]), fmt(r["rx"]), r["fill"])


def emit_circle(c, indent="    "):
    return '%s<circle id="%s" cx="%s" cy="%s" r="%s" fill="%s"/>' % (
        indent, c["id"], fmt(c["cx"]), fmt(c["cy"]), fmt(c["r"]), c["fill"])


def emit_svg(panel):
    stem = panel["stem"]
    lines = []
    lines.append('<?xml version="1.0" encoding="UTF-8" standalone="no"?>')
    lines.append('<!--')
    lines.append('  Voxglitch "%s" panel. Generated by scripts/generate_vx_drums_panels.py; do not hand-edit, regenerate.' % panel["name"])
    lines.append('  %d HP = %s mm = %d px (RACK_GRID_WIDTH 15 x %d). Height 128.5 mm to match the other Voxglitch panels.' % (N_HP, fmt(W_MM), W_PX, N_HP))
    lines.append('  viewBox is 1:1 with Rack pixels, so every coordinate here IS a Rack coordinate.')
    if any(r["layer"] == "anchors" for r in panel["rects"]):
        lines.append('  Dark variant: python3 scripts/generate_dark_panel.py res/modules/%s/%s.svg (the generator script runs it' % (panel["res_dir"], stem))
        lines.append('  and re-inserts the *_display plate, which the dark pass strips).')
    else:
        lines.append('  Dark variant: python3 scripts/generate_dark_panel.py res/modules/%s/%s.svg (the generator script runs it).' % (panel["res_dir"], stem))
    lines.append('  Ids ending _input/_output/_knob/_button/_switch/_light are the contract with %s' % panel["widget"])
    lines.append('  (PanelHelper::findNamed); %s are read with findNamedRect.' % ", ".join(r["id"] for r in panel["rects"]))
    lines.append('  House style: flat background; rounded plates (rx 4.5) behind output clusters only; labels are Pilat Bold 7 pt')
    lines.append('  outlines (no text elements); jack markers r %s; knob/switch/button/light anchor dots r %s (timeline idiom).' % (fmt(PORT_R), fmt(DOT_R)))
    lines.append('  Every colour is a key of the generate_dark_panel.py COLOR_MAP (plus the dot and dark-plate pass-throughs).')
    lines.append('  Screw squares x 15..30 and %d..%d, y 0..15 and %d..%d are kept clear of anchors.' % (W_PX - 2 * SCREW, W_PX - SCREW, RACK_GRID_HEIGHT - SCREW, RACK_GRID_HEIGHT))
    for note in panel["notes"]:
        lines.append('  ' + note)
    lines.append('-->')
    lines.append('<svg version="1.1" id="%s"' % stem)
    lines.append('     width="%smm" height="%smm" viewBox="%s"' % (fmt(W_MM), fmt(PANEL_H_MM), VIEWBOX))
    lines.append('     xmlns="%s" xmlns:svg="%s"' % (SVG_NS, SVG_NS))
    lines.append('     xmlns:inkscape="%s"' % INK_NS)
    lines.append('     xmlns:sodipodi="%s"' % SODI_NS)
    lines.append('     sodipodi:docname="%s.svg">' % stem)
    lines.append('  <sodipodi:namedview id="namedview1" pagecolor="#ffffff" inkscape:document-units="mm"></sodipodi:namedview>')

    lines.append('  <g inkscape:groupmode="layer" inkscape:label="background" id="layer_background">')
    lines.append('    <rect id="panel_background" x="0" y="0" width="%d" height="%s" fill="%s"/>' % (W_PX, fmt(H_PX), COL_BG))
    lines.append('    <!-- plates only behind output clusters (house rule); named rects for code-drawn widgets (findNamedRect) -->')
    for r in panel["rects"]:
        if r["layer"] == "background":
            lines.append(emit_rect(r))
    for rl in panel.get("rules", []):
        lines.append('    <line id="%s" x1="%s" y1="%s" x2="%s" y2="%s" stroke="%s" stroke-opacity="%s" stroke-width="%s"/>' % (
            rl["id"], fmt(rl["x"]), fmt(rl["y1"]), fmt(rl["x"]), fmt(rl["y2"]), COL_INK, INK_OPACITY, fmt(rl["width"])))
    lines.append('  </g>')

    lines.append('  <g inkscape:groupmode="layer" inkscape:label="branding" id="layer_branding">')
    lines.extend(emit_branding(panel["name"]))
    lines.append('  </g>')

    lines.append('  <g inkscape:groupmode="layer" inkscape:label="anchors" id="layer_anchors">')
    lines.append('    <!-- widget anchors: top-level, untransformed; PanelHelper reads the centre of each id (light file only) -->')
    for a in panel["anchors"]:
        lines.append(emit_circle(a))
    for r in panel["rects"]:
        if r["layer"] == "anchors":
            lines.append(emit_rect(r))
    lines.append('  </g>')

    lines.append('  <g inkscape:groupmode="layer" inkscape:label="labels" id="layer_labels">')
    lines.append('    <!-- Pilat Bold %s px outlines, tracking %s px, GPOS kerning; ink-centred on cx, baseline as given -->' % (fmt(SIZE_LABEL), fmt(TRACK_LABEL)))
    for lb in panel["labels"]:
        lines.append(text_paths(lb["text"], lb["cx"], lb["baseline"], LABEL_GLYPHS, LABEL_KERN, SIZE_LABEL,
                                tracking=TRACK_LABEL, word_extra=0.0, elem_id=lb["id"]))
    lines.append('  </g>')
    lines.append('</svg>')
    return "\n".join(lines) + "\n"


# ----------------------------------------------------------------------------------------
# Validation
# ----------------------------------------------------------------------------------------

def load_dark_generator(scripts_dir):
    path = scripts_dir / "generate_dark_panel.py"
    spec = importlib.util.spec_from_file_location("generate_dark_panel", str(path))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def q(tag):
    return "{%s}%s" % (SVG_NS, tag)


def local(tag):
    return tag.split("}", 1)[1] if "}" in tag else tag


def scan_colours(text):
    """Every hex colour in the rendered document: XML comments never render and the namedview's
    pagecolor is Inkscape UI state, so both are ignored; everything else (fill/stroke in style
    or attribute form, which is all the dark generator rewrites) is checked."""
    body = re.sub(r"<!--.*?-->", "", text, flags=re.S)
    body = re.sub(r"<sodipodi:namedview.*?</sodipodi:namedview>", "", body, flags=re.S)
    return set(c.lower() for c in re.findall(r"#[0-9a-fA-F]{3,6}\b", body))


def screw_squares():
    return [(SCREW, 2 * SCREW, 0, SCREW), (W_PX - 2 * SCREW, W_PX - SCREW, 0, SCREW),
            (SCREW, 2 * SCREW, RACK_GRID_HEIGHT - SCREW, RACK_GRID_HEIGHT),
            (W_PX - 2 * SCREW, W_PX - SCREW, RACK_GRID_HEIGHT - SCREW, RACK_GRID_HEIGHT)]


def in_screw_square(x, y):
    return any(x0 <= x <= x1 and y0 <= y <= y1 for x0, x1, y0, y1 in screw_squares())


def validate_light(text, panel, color_map):
    errors = []
    root = ET.fromstring(text)

    # root geometry: width mm must equal viewBox px / 2.952756
    width = root.get("width", "")
    vb = root.get("viewBox", "")
    if not width.endswith("mm") or vb != VIEWBOX:
        errors.append("root width/viewBox: %r %r" % (width, vb))
    else:
        vb_w = float(vb.split()[2])
        if abs(float(width[:-2]) - vb_w / MM2PX) > 1e-3:
            errors.append("width %s mm != viewBox %s px / 2.952756" % (width, vb_w))
    if root.get("height") != "%smm" % fmt(PANEL_H_MM):
        errors.append("root height %r" % root.get("height"))

    # forbidden content
    for bad in ("text", "style", "use", "clipPath", "mask", "filter", "image", "linearGradient", "radialGradient"):
        if next(root.iter(q(bad)), None) is not None:
            errors.append("forbidden element <%s>" % bad)
    if "url(#" in text:
        errors.append("file contains url(#")
    if any(el.get("class") for el in root.iter()):
        errors.append("class attribute present")

    # ids unique
    seen = {}
    for el in root.iter():
        eid = el.get("id")
        if eid is None:
            continue
        if eid in seen:
            errors.append("duplicate id %r" % eid)
        seen[eid] = el
        if len(eid) > 63:
            errors.append("id %r longer than 63 chars (NanoSVG truncates)" % eid)

    # layers: direct children of the root, untransformed
    layers = {}
    for child in root:
        if child.tag == q("g") and child.get("{%s}groupmode" % INK_NS) == "layer":
            layers[child.get("id")] = child
            if child.get("transform"):
                errors.append("layer %r carries a transform" % child.get("id"))
    for want in ("layer_background", "layer_branding", "layer_anchors", "layer_labels"):
        if want not in layers:
            errors.append("missing layer %r" % want)
    if errors:
        raise PanelError("\n".join(errors))

    # anchors: every placeholder-suffixed id is a top-level untransformed circle/rect in the anchors layer
    anchors_layer = layers["layer_anchors"]
    anchor_ids = []
    table = {a["id"]: a for a in panel["anchors"]}
    table.update({r["id"]: r for r in panel["rects"] if r["layer"] == "anchors"})
    for el in anchors_layer:
        if el.tag not in (q("circle"), q("rect")):
            errors.append("non-anchor element <%s> in the anchors layer" % local(el.tag))
            continue
        eid = el.get("id") or ""
        if not PLACEHOLDER_RE.match(eid) or eid.endswith("_attn"):
            errors.append("anchor id %r does not end in a placeholder suffix" % eid)
        if el.get("transform"):
            errors.append("anchor %r carries a transform" % eid)
        suffix = eid.rsplit("_", 1)[-1]
        fill = el.get("fill")
        if el.tag == q("circle"):
            cx, cy, r = float(el.get("cx")), float(el.get("cy")), float(el.get("r"))
            if suffix in ("input", "output"):
                if r != PORT_R or fill != COL_MARK:
                    errors.append("jack anchor %r must be r %s fill %s" % (eid, PORT_R, COL_MARK))
            elif suffix in ("knob", "button", "switch", "light"):
                if r != DOT_R or fill != COL_DOT:
                    errors.append("dot anchor %r must be r %s fill %s" % (eid, DOT_R, COL_DOT))
            else:
                errors.append("circle anchor %r has suffix %r" % (eid, suffix))
            if not (PORT_R <= cx <= W_PX - PORT_R and 0 < cy < H_PX):
                errors.append("anchor %r centre (%s, %s) is off-panel or too close to the edge" % (eid, cx, cy))
        else:
            cx = float(el.get("x")) + float(el.get("width")) / 2.0
            cy = float(el.get("y")) + float(el.get("height")) / 2.0
            if suffix != "display":
                errors.append("rect anchor %r must end in _display" % eid)
            if fill != COL_DARK_PLATE:
                errors.append("display rect %r must be %s" % (eid, COL_DARK_PLATE))
        if in_screw_square(cx, cy):
            errors.append("anchor %r centre (%s, %s) is inside a screw square" % (eid, cx, cy))
        ref = table.get(eid)
        if ref is None:
            errors.append("anchor %r is not in the geometry table" % eid)
        elif el.tag == q("circle") and (float(ref["cx"]) != cx or float(ref["cy"]) != cy):
            errors.append("anchor %r round-trip mismatch" % eid)
        anchor_ids.append(eid)
    missing = [k for k in table if k not in anchor_ids]
    if missing:
        errors.append("anchors in the table but not emitted: %s" % missing)
    for eid, el in seen.items():
        if PLACEHOLDER_RE.match(eid) and el not in list(anchors_layer):
            errors.append("placeholder id %r outside the anchors layer (<%s>)" % (eid, local(el.tag)))

    # named rects: untransformed rects in the background layer
    bg = layers["layer_background"]
    for r in panel["rects"]:
        if r["layer"] != "background":
            continue
        el = seen.get(r["id"])
        if el is None or el.tag != q("rect") or el not in list(bg) or el.get("transform"):
            errors.append("named rect %r must be an untransformed <rect> in the background layer" % r["id"])
        elif not NAMED_RECT_RE.match(r["id"]):
            errors.append("named rect id %r should end in _area or _plate" % r["id"])
        elif el.get("fill") != COL_PLATE:
            errors.append("named rect %r must be %s" % (r["id"], COL_PLATE))

    # labels: every label group is present, contains only id-less paths
    labels_layer = layers["layer_labels"]
    for lb in panel["labels"]:
        el = seen.get(lb["id"])
        if el is None or el.tag != q("g") or el not in list(labels_layer):
            errors.append("label group %r missing from the labels layer" % lb["id"])
            continue
        for p in el:
            if p.tag != q("path") or p.get("id") or not p.get("transform", "").startswith("matrix("):
                errors.append("label %r must contain only id-less transformed <path>s" % lb["id"])
                break

    # colours: only what generate_dark_panel.py maps, plus the two deliberate pass-throughs
    allowed = set(color_map.keys()) | {COL_DOT, COL_DARK_PLATE}
    stray = sorted(scan_colours(text) - allowed)
    if stray:
        errors.append("colours not in COLOR_MAP: %s" % stray)

    if errors:
        raise PanelError("\n".join(errors))
    return anchor_ids


def validate_dark(text, panel, color_map):
    errors = []
    root = ET.fromstring(text)
    reinserted = {r["id"] for r in panel["rects"] if r["layer"] == "anchors"}

    bg = [el for el in root.iter(q("rect")) if el.get("id") == "dark_background"]
    if len(bg) != 1 or "fill:#18181a" not in (bg[0].get("style") or ""):
        errors.append("dark_background rect missing or not #18181a")

    for el in root.iter():
        eid = el.get("id") or ""
        if PLACEHOLDER_RE.match(eid):
            if el.tag == q("rect") and eid in reinserted:
                continue
            errors.append("placeholder %r (<%s>) survived the dark pass" % (eid, local(el.tag)))
    for el in root.iter(q("circle")):
        errors.append("circle %r survived the dark pass" % (el.get("id") or "?"))

    light_only = {k for k, v in color_map.items() if k != v} | {COL_DOT, COL_MARK}
    found = scan_colours(text)
    leftover = sorted(found & light_only)
    if leftover:
        errors.append("light-theme colours left in the dark file: %s" % leftover)
    allowed = set(color_map.values()) | {COL_DARK_PLATE}
    unmapped = sorted(found - allowed - light_only)
    if unmapped:
        errors.append("unmapped colours in the dark file: %s" % unmapped)
    if "url(#" in text or next(root.iter(q("text")), None) is not None:
        errors.append("dark file contains url(# or <text>")

    if errors:
        raise PanelError("\n".join(errors))
    return sorted(found)


# ----------------------------------------------------------------------------------------
# Dark pass, PNG previews
# ----------------------------------------------------------------------------------------

def run_dark_generator(scripts_dir, light_path):
    cmd = [sys.executable, str(scripts_dir / "generate_dark_panel.py"), str(light_path)]
    proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, universal_newlines=True)
    if proc.returncode != 0:
        raise PanelError("generate_dark_panel.py failed (rc %d):\n%s" % (proc.returncode, proc.stdout))
    return proc.stdout


def reinsert_display_rects(dark_text, panel):
    """generate_dark_panel.py strips ids ending in _display; the readout plate must be dark in
    both themes, so put it back inside the (now empty) anchors layer. PanelHelper never reads
    the dark file, so the id is cosmetic there; keeping it lets Inkscape work see the same tree."""
    rects = [r for r in panel["rects"] if r["layer"] == "anchors"]
    if not rects:
        return dark_text
    m = re.search(r'<g[^>]*id="layer_anchors"[^>]*>', dark_text)
    if not m:
        raise PanelError("dark file has no layer_anchors group to re-insert into")
    block = "\n    <!-- re-inserted by scripts/generate_vx_drums_panels.py: the dark pass strips *_display ids, and this plate must stay dark in both themes -->"
    for r in rects:
        block += "\n" + emit_rect(r)
    return dark_text[:m.end()] + block + dark_text[m.end():]


def wslpath_w(path):
    return subprocess.check_output(["wslpath", "-w", str(path)], universal_newlines=True).strip()


def render_png(svg_path, png_path):
    """900 px wide preview through the Windows Inkscape; returns a status string, never raises."""
    if not os.path.exists(INKSCAPE_WIN):
        return "skipped (no %s)" % INKSCAPE_WIN
    if shutil.which("wslpath") is None:
        return "skipped (wslpath not available; not running under WSL)"
    png_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        cmd = [INKSCAPE_WIN, "--export-type=png", "--export-width=900",
               "--export-filename=" + wslpath_w(png_path), wslpath_w(svg_path)]
        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                              universal_newlines=True, timeout=300)
    except (OSError, subprocess.SubprocessError) as exc:
        return "failed: %s" % exc
    if proc.returncode != 0 or not png_path.exists():
        return "failed (rc %d): %s" % (proc.returncode, proc.stdout.strip()[-400:])
    return "ok (%d bytes)" % png_path.stat().st_size


# ----------------------------------------------------------------------------------------
# main
# ----------------------------------------------------------------------------------------

def write_if_changed(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    old = path.read_text(encoding="utf-8") if path.exists() else None
    if old != text:
        path.write_text(text, encoding="utf-8")
    return old is None, old is not None and old != text


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--repo-root", default=None, help="repository root (default: parent of this script's directory)")
    ap.add_argument("--render-png", action="store_true", help="render 900 px PNG previews into docs/modules/<kebab>/ via Windows Inkscape")
    ap.add_argument("--ids-file", default=None, help="write the anchor / named-rect id list (grouped per panel) to this path")
    args = ap.parse_args(argv)

    scripts_dir = Path(__file__).resolve().parent
    root = Path(args.repo_root).resolve() if args.repo_root else scripts_dir.parent
    color_map = load_dark_generator(scripts_dir).COLOR_MAP

    try:
        self_test()
        print("self-test: embedded glyph tables reproduce the reference label widths")
        ids_report = []
        for panel in (kit_panel(), sequencer_panel()):
            res_dir = root / "res" / "modules" / panel["res_dir"]
            light_path = res_dir / (panel["stem"] + ".svg")
            dark_path = res_dir / (panel["stem"] + "-dark.svg")

            light = emit_svg(panel)
            anchor_ids = validate_light(light, panel, color_map)
            created, changed = write_if_changed(light_path, light)
            print("\n== %s ==" % panel["name"])
            print("light: %s (%d bytes, %s)" % (light_path, len(light.encode("utf-8")),
                                                "created" if created else ("updated" if changed else "unchanged")))
            jacks = [a for a in panel["anchors"] if a["r"] == PORT_R]
            dots = [a for a in panel["anchors"] if a["r"] == DOT_R]
            print("  anchors: %d jacks, %d dots, %d display rect(s); named rects: %s; labels: %d"
                  % (len(jacks), len(dots), sum(1 for r in panel["rects"] if r["layer"] == "anchors"),
                     [r["id"] for r in panel["rects"] if r["layer"] == "background"], len(panel["labels"])))
            print("  light validation: OK")

            log = run_dark_generator(scripts_dir, light_path)
            print("  dark pass (scripts/generate_dark_panel.py):")
            for line in log.strip().splitlines():
                print("    " + line)
            dark = reinsert_display_rects(dark_path.read_text(encoding="utf-8"), panel)
            dark_colours = validate_dark(dark, panel, color_map)
            dark_path.write_text(dark, encoding="utf-8")
            print("dark:  %s (%d bytes); colours present: %s" % (dark_path, len(dark.encode("utf-8")), dark_colours))
            print("  dark validation: OK (anchors stripped, colours mapped, nothing unmapped)")

            if args.render_png:
                docs_dir = root / "docs" / "modules" / panel["docs_dir"]
                for svg, png in ((light_path, docs_dir / "front-panel.png"), (dark_path, docs_dir / "front-panel-dark.png")):
                    print("  png:   %s <- %s: %s" % (png, svg.name, render_png(svg, png)))

            ids_report.append("# %s.svg (res/modules/%s): anchors, PanelHelper::findNamed" % (panel["stem"], panel["res_dir"]))
            ids_report.extend(i for i in anchor_ids if not i.endswith("_display"))
            ids_report.append("# %s.svg: named rects, PanelHelper::findNamedRect" % panel["stem"])
            ids_report.extend(r["id"] for r in panel["rects"])
            ids_report.append("")
    except PanelError as exc:
        print("\nERROR:\n%s" % exc, file=sys.stderr)
        return 1

    if args.ids_file:
        Path(args.ids_file).write_text("\n".join(ids_report), encoding="utf-8")
        print("\nids written to %s" % args.ids_file)
    print("\nALL OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
